"""Add installation tests to the formula generated by the official CLI release."""
from pathlib import Path
import re
import sys

TEST = '''  test do
    assert_match version.to_s, shell_output("#{bin}/miilo --version")
    assert_match version.to_s, shell_output("#{bin}/miilo-local --version")
  end
'''


def prepare(source, tag):
    if not re.fullmatch(r'v\d+\.\d+\.\d+', tag):
        raise ValueError('A stable version tag is required')
    urls = re.findall(r'^\s+url "([^"]+)"', source, re.M)
    expected = 'https://github.com/miilo-ai/miilo-cli/releases/download/' + tag + '/'
    if len(urls) != 4 or any(not url.startswith(expected) for url in urls):
        raise ValueError('Formula must use the four matching official release archives')
    version = re.search(r'^  version "([^"]+)"\n', source, re.M)
    if version:
        if version.group(1) != tag[1:]:
            raise ValueError('Formula version differs from release tag')
        source = source[:version.start()] + source[version.end():]
    if '  test do\n' not in source:
        if not source.endswith('end\n'):
            raise ValueError('Unexpected formula structure')
        source = source[:-4] + TEST + 'end\n'
    return source


if __name__ == '__main__':
    path, tag = Path(sys.argv[1]), sys.argv[2]
    path.write_text(prepare(path.read_text(), tag))
